"""Render the revised manuscript source directly from audited result tables."""
from pathlib import Path
import json
import pandas as pd
from lag_audit.campaign import SUBMISSIONS
S=Path('results/summary');overview=json.loads((S/'overview.json').read_text());p=pd.read_csv(S/'primary.csv');mean=pd.read_csv(S/'primary_mean.csv').set_index('policy')
labels=dict(zip(SUBMISSIONS,['Claude 3.5 Sonnet','GPT-4o','GPT-4','Claude 3 Opus','Claude 4 Sonnet']))
policies=['hard_cap','zcl_settled','zcl_committed','zcl_expected_inflight','lag_structural']

def table(caption,label,headers,rows,align=None):
 align=align or 'l'+'r'*(len(headers)-1)
 body='\n'.join(' & '.join(map(str,row))+r' \\' for row in rows)
 return r'\begin{table}[tbp]\centering\small'+'\n'+r'\caption{'+caption+'}'+r'\label{'+label+'}\n'+r'\begin{tabular}{'+align+'}\n'+r'\toprule'+'\n'+' & '.join(headers)+r' \\ \midrule'+'\n'+body+'\n'+r'\bottomrule\end{tabular}\end{table}'

replacements={}
replacements['ABSTRACT_RESULTS']=f"The replay uses 2,398 usable records from 2,404 available trajectories and evaluates {overview['episodes']:,} single-submission policy/block episodes. In the predeclared primary setting, structural lag-aware pricing averages 3.525 resolutions per block versus 1.475 for committed ZCL, 3.400 for expected-in-flight ZCL and 3.375 for a cap. Rechecking prices after refunds raises committed ZCL to 3.375, and the lag-aware advantage over the expected-in-flight baseline reverses on the common-complete-issue subset. Gains are therefore protocol- and baseline-dependent."
t=pd.read_csv('results/theory-extended-002/table5.csv')
replacements['THEORY_TABLE']=table('Recomputed analytic values corresponding to the original Table 5. These are theoretical ratios, not empirical resolution rates.','tab:theory',['$U/L$','$d$','$B(d)$','$\\beta^*(d)$'],[[int(r.ratio),f'{r.delta:.2f}',f'{r.zcl:.3f}',f'{r.lag:.3f}'] for r in t.itertuples()])
c=pd.read_csv('results/theory-extended-002/convergence.csv')
replacements['CONVERGENCE_TEXT']=f"The maximum relative error against the asymptotic target is {100*c[c.units==4000].relative_error.max():.4f}\\% at 4000 units and {100*c[c.units==16000].relative_error.max():.4f}\\% at 16000 units; these are finite-resolution discrepancies, not confidence intervals."
d=pd.read_csv('results/data-audit/summary.csv')
replacements['DATA_TABLE']=table('Archive coverage and usable records. The five submissions reuse the same benchmark issues. Missing trajectories include 12 officially resolved Opus runs.','tab:data',['Configuration','Trajectories','Usable','Missing','Unknown'],[[labels[r.submission],r.archive_trajectories,r.retained,r.missing_trajectory,r.unknown_outcome] for r in d.itertuples()]+[['Total',2404,2398,96,6]])
replacements['MISSINGNESS_TEXT']='There are 96 missing trajectories and six additional unknown-outcome exclusions. The retained records include 796 successful runs; these are not 796 unique issues. All retained costs are positive and below the chosen \\$6 reservation. The common-complete-issue sensitivity contains 409 issues per submission.'
rows=[]
for sub in SUBMISSIONS:
 g=p[p.submission==sub].set_index('policy');rows.append([labels[sub]]+[f'{g.loc[policy].resolved_before_deadline:.3f}' for policy in policies])
rows.append(['Mean across configurations']+[f'{mean.loc[policy].resolved_before_deadline:.3f}' for policy in policies])
replacements['PRIMARY_TABLE']=table('Primary setting: mean resolutions completed by the 600-second deadline, eight blocks per configuration. Cap, settled ZCL, committed ZCL, expected-in-flight ZCL and structural lag-aware pricing use identical offered jobs.','tab:primary',['Configuration','Cap','Settled','Committed','Expected','Lag-aware'],rows)
ci=pd.read_csv(S/'paired_comparisons.csv');ci=ci[(ci.submission=='five_submission_mean')&(ci.bootstrap_block_length==2)]
contrastnames={'zcl_committed':'committed ZCL','zcl_settled':'settled ZCL','zcl_expected_inflight':'expected-in-flight ZCL','hard_cap':'cap'}
rows=[[('Lag-aware' if r.policy=='lag_structural' else 'Committed ZCL')+' minus '+contrastnames[r.baseline],f'{r.mean_difference:+.3f}',f'[{r.ci95_low:+.3f}, {r.ci95_high:+.3f}]'] for r in ci.itertuples()]
replacements['PRIMARY_CI_TABLE']=table('Predeclared primary contrasts. Descriptive 95\\% moving-block intervals, block length 2. The resampling unit is the eight common blocks after averaging submissions within each block. Block lengths 1 and 4 are also published.','tab:ci',['Contrast','Difference','Interval'],rows)
replacements['RESULTS_TEXT']='The final single-submission run completes 107,160 episodes with zero recorded failures. It covers 13,395 scenario/policy cells, including 400 primary episodes. Validation checks 9,930,622 saved decision/settlement events with no budget, ledger or feedback-provenance violations. Structural design bounds are never exceeded. The nominal worker limits reach 64, but the largest observed occupancy is 16 in the single-submission grid and four in the primary setting. These counts cannot establish performance with 64 simultaneously running jobs.\n\nTable~\\ref{tab:primary} retains the mixed results. Lag-aware pricing exceeds committed ZCL in each configuration in the primary condition, but falls below the cap on Claude 3.5 Sonnet, GPT-4 and Claude 3 Opus. The mean increment over expected-in-flight ZCL is only 0.125 resolutions per block; its descriptive interval includes zero. The very large increment over committed ZCL is therefore not evidence of a similarly large increment over an already strong alternative.\n'
q=pd.read_csv(S/'queue_sensitivity.csv');rows=[]
for policy in policies:
 g=q[(q.policy==policy)&(q.workers==16)].set_index('queue_mode');rows.append([{'hard_cap':'Hard cap','zcl_settled':'Settled ZCL','zcl_committed':'Committed ZCL','zcl_expected_inflight':'Expected-in-flight ZCL','lag_structural':'Structural lag-aware'}[policy]]+[f'{g.loc[queue].resolved_before_deadline:.3f}' for queue in ['strict','paper','defer']])
replacements['QUEUE_TEXT']='At the same primary parameters, changing the queue from immediate price rejection to rechecking after refunds raises committed ZCL from 1.475 to 3.375 resolutions per block. The structural lag-aware mean remains 3.525. Thus most of its 2.050 increment over committed ZCL in the paper queue disappears when the queue rechecks prices. The strict room-first condition performs poorly for all policies because it irrevocably discards jobs while reservations occupy the budget. This is a measured interaction between policy and queue semantics.\n'+table('Queue sensitivity at the primary budget, reservation and worker limit. Means across five configurations and eight blocks.','tab:queues',['Policy','Strict','Paper','Defer'],rows)
pool=pd.read_csv(S/'pooling.csv');pool=pool[(pool.workers==16)&(pool.queue_mode=='paper')]
names={'equal_private_cap':'Equal private cap','equal_private_zcl':'Equal private ZCL','learned_private_cap':'Historical static cap','learned_private_zcl':'Historical static ZCL','shared_cap':'Shared cap','shared_lag_structural':'Shared lag-aware','shared_zcl_committed':'Shared committed ZCL','shared_zcl_expected':'Shared expected-in-flight ZCL','shared_zcl_settled':'Shared settled ZCL'}
rows=[[names[r.policy],f'{r.resolved_before_deadline:.3f}',f'{r.unique_issues_before_deadline:.3f}',f'{r.spend:.2f}'] for r in pool.itertuples()]
replacements['POOL_TABLE']='The pooling sensitivity has 648 episodes. In the paper-queue, 16-worker cell, shared lag-aware pricing produces 33.250 successful runs and 28.375 unique resolved issues per block, compared with 16.125 runs and 7.500 unique issues for a shared cap. Shared committed ZCL produces 25.000 runs; expected-in-flight ZCL produces 27.875. This result supports value-aware allocation in this particular pooled workload, but it does not reproduce the original rotated protocol. Static private allocations interact with head-of-line waiting and are not guaranteed to spend their full allocation. All worker/queue cells, including the defer condition, are published.\n'+table('Modified pooling protocol, paper queue, 16 total workers and \\$120 shared total budget. Independent successful runs and unique issues are distinct endpoints. Eight paired blocks.','tab:pool',['Policy','Successful runs','Unique issues','Spend (\\$)'],rows)
sw=pd.read_csv(S/'switches.csv');rows=[]
for name,label in [('hard_cap','Cap'),('zcl_committed','Committed ZCL'),('fixed_previous_day_full_archive','Previous-day fixed'),('banded_previous_day_full_archive','Previous-day banded')]:
 g=sw[sw.policy==name].set_index('relative_block');rows.append([label]+[f'{g.loc[k].resolved_before_deadline:.3f}' for k in [-1,0,1]])
replacements['SWITCH_TABLE']='The switch sensitivity contains 60 ordered-pair/switch-block scenarios and 1,920 recorded policy/block episodes. On the block after a switch, previous-day banding averages 2.117 resolutions versus 1.700 for the unbanded forecast and 2.050 for committed ZCL. This is a modest descriptive advantage in a privileged full-archive condition, not proof of a deployable learning guarantee or a reproduction of the original 120 scenarios.\n'+table('Model-switch sensitivity: mean resolutions by deadline over all 60 scenarios. Feedback includes all previous offered outcomes and is privileged. Scenarios reuse issues and are not independent samples.','tab:switch',['Policy','Before','Switch','After'],rows)
replacements['SENSITIVITY_TEXT']='On the 409 common-complete issues, mean primary resolutions are 3.375 for structural lag-aware pricing, 3.450 for expected-in-flight ZCL, 3.400 for settled ZCL and 3.375 for the cap. The ordering of close baselines is therefore sensitive to which issues have complete records. This finding is retained rather than selecting a preferred denominator.\n\nAcross the full grid, 102,139 of 107,160 episodes contain at least one predicted density outside the warm-up 5th--95th percentile range. The values are monitored rather than clipped to fabricate a theorem premise. Calibration, AUC, cost error, rejection counts, realized occupancy, utilization and late completions accompany every episode. Policy-specific learning, larger reservations and budgets, time proxies and deadlines are reported as sensitivities, with all predeclared comparisons available in CSV. No population-level significance claim is made.'
text=Path('paper/manuscript-template.tex').read_text()
for key,value in replacements.items():text=text.replace('%%'+key+'%%',value)
assert '%%' not in text
Path('paper/revised-paper.tex').write_text(text)
print('Wrote self-contained revised-paper.tex')
